            reportFailure(context, FileError::INVALID_STATE_ERR);
            return;
        }

        // Create a new task that ensures the callback is executed on the main thread
        auto task = createCrossThreadTask([this, callbacks]() {
            // Execute the callback on the main thread
            callbacks->execute();
        });

        // Post the task to the main thread
