  DCHECK(GetGuestView());

  // Define a safe maximum length for the URL
  const size_t kMaxUrlLength = 1024;

  // Ensure the URL does not exceed the maximum length
  std::string url("about:blank");
  if (url.size() > kMaxUrlLength) {
    LOG(ERROR) << "URL exceeds maximum length (" << url.size() << " bytes)";
    return;
  }

  NavigateToAboutBlank(url);
  base::PostDelayedTaskWithTraits(
      FROM_HERE, {BrowserThread::UI},
